using System.Text.Json; using FFP.Purchasing.Tablet.Models;
namespace FFP.Purchasing.Tablet.Services;
public interface ILocalItemCache { Task<IReadOnlyList<LearnedItem>> SearchAsync(string? text=null); Task LearnAsync(string description,string uom,decimal price); Task ClearAsync(); }
public sealed class LocalItemCache:ILocalItemCache {
 private readonly string _path=Path.Combine(FileSystem.AppDataDirectory,"learned-items.json"); private readonly SemaphoreSlim _gate=new(1,1); private static readonly JsonSerializerOptions Json=new(JsonSerializerDefaults.Web){WriteIndented=true};
 public async Task<IReadOnlyList<LearnedItem>> SearchAsync(string? text=null){var all=await ReadAsync();if(string.IsNullOrWhiteSpace(text))return all.OrderByDescending(x=>x.LastUsedAt).ToList();return all.Where(x=>x.Description.Contains(text,StringComparison.OrdinalIgnoreCase)).OrderByDescending(x=>x.UsageCount).ThenByDescending(x=>x.LastUsedAt).ToList();}
 public async Task LearnAsync(string description,string uom,decimal price){var normalized=Normalize(description);if(normalized.Length==0)return;await _gate.WaitAsync();try{var all=await ReadUnsafeAsync();var x=all.FirstOrDefault(i=>i.NormalizedDescription==normalized);if(x is null){x=new LearnedItem{NormalizedDescription=normalized,Description=description.Trim()};all.Add(x);}x.Description=description.Trim();x.LastUom=string.IsNullOrWhiteSpace(uom)?"EA":uom.Trim().ToUpperInvariant();x.LastPrice=price;x.UsageCount++;x.LastUsedAt=DateTimeOffset.Now;await File.WriteAllTextAsync(_path,JsonSerializer.Serialize(all,Json));}finally{_gate.Release();}}
 public Task ClearAsync(){if(File.Exists(_path))File.Delete(_path);return Task.CompletedTask;} private async Task<List<LearnedItem>> ReadAsync(){await _gate.WaitAsync();try{return await ReadUnsafeAsync();}finally{_gate.Release();}} private async Task<List<LearnedItem>> ReadUnsafeAsync(){if(!File.Exists(_path))return[];try{return JsonSerializer.Deserialize<List<LearnedItem>>(await File.ReadAllTextAsync(_path),Json)??[];}catch{return[];}} private static string Normalize(string s)=>string.Join(' ',s.Trim().ToUpperInvariant().Split(' ',StringSplitOptions.RemoveEmptyEntries));
}